  last_funding = EXCLUDED.last_funding, data = EXCLUDED.data, updated_at = now();

INSERT INTO research_companies (name, code, industry, seg, listed, round, cap, valuation, rev, last_funding, data)
VALUES ('青禾晶元', '—', 'semiconductor', 'equipment', false, 'C+ 轮', NULL, 79.5, NULL, '2026-10', '{"name":"青禾晶元","code":"—","industry":"semiconductor","seg":"equipment","listed":false,"desc":"青禾晶元半导体科技（集团）股份有限公司（2020-07-08 成立，原名北京青禾晶元半导体科技，2026 年完成股份制改革并更现名，总部已迁至天津滨海高新区），由母凤文博士（清华大学机械系硕士、东京大学博士，原中科院微电子所研究员，国家级海外高层次人才）创立。公司定位「先进半导体键合集成技术与方案提供商」，以「高端键合装备制造 + 精密键合工艺服务」双轮驱动，构建「材料—工艺—装备」全产业链闭环。装备端已形成四大自主知识产权产品矩阵：超高真空常温键合系统、混合键合设备、热压（TCB）键合装备、临时键合/解键合装备，另配套表面处理（超原子束 TRIM）设备；键合设备覆盖 4/6/8/12 英寸全尺寸。① SAB61 系列超高真空常温键合设备采用超高真空离子束轰击活化表面，无需加热或退火即可形成牢固化学键，支持 SiC、Ga2O3、金刚石等异质材料键合，无热应力、无界面氧化层；② SAB62 系列亲水性键合与混合键合设备通过等离子体活化 + 旋涂清洗富集羟基，室温键合后经退火获得高强度介质键合与铜铜互连，用于 POI/SOI 衬底、MEMS 晶圆级封装、3D 堆叠 CIS；③ SAB82 系列 C2W 混合键合设备无需凸点即可铜对铜直接键合，支持 <10μm 高密度互联间距与 KGD 芯片筛选，是 Chiplet 先进封装核心装备；④ SAB64 系列临时键合/解键合设备支持 3μm 以内 TTV 与超薄晶圆解键合。材料端 SiC、LNOI（薄膜铌酸锂）、POI 复合衬底已量产并达国际先进水平，金刚石 Smart-Cut 国内率先突破，另开发 Dual LNOI、GeOI、SiCOI 等新工艺。工艺平台拥有十级/百级洁净间超 2000 ㎡、百余台设备、50 余名工程师，以 H-cut + 减薄键合路线覆盖 4/6/8 英寸晶圆加工，可提供从材料到产线的 Turnkey 交钥匙方案。厂区面积 3 万㎡，5 大研发生产中心，国内外专利 200 余项；常温键合装备获评国家颠覆性技术创新重点专项、全国首批六大标杆项目之一；全资/控股子公司含天津中科晶禾电子科技、青禾晶元（天津）半导体材料、青禾晶元（晋城）半导体材料。计划 2027 年申报上市。","valuation":79.5,"round":"C+ 轮","lastFunding":"2026-10","latestFunding":"2026-10 · 中微公司子公司中微临港增资（本轮投前估值 67.5 亿元，中微临港+17 方合计增资 2.5 亿元）","execChanges":[],"latestTech":"2025 年发布全球首台自主研发 C2W & W2W 双模式 SAB8210CWW 设备；12 英寸 TCB 键合设备交付、超原子束设备自主研发成功；常温键合装备获评国家颠覆性技术创新重点专项并成为全国首批六大标杆项目之一；2025 年键合设备新增订单近 5 亿元（2024 年超 3 亿元）","tech":[{"date":"2026","title":"完成股份制改革，正式更名为青禾晶元半导体科技（集团）股份有限公司"},{"date":"2025","title":"发布全球首台自主研发 C2W & W2W 双模式 SAB8210CWW 设备；异质集成设备二期产线投产，年产能超百台；整线方案获头部客户订单，实现「材料—工艺—装备」闭环落地"},{"date":"2024","title":"键合设备实现批量销售，全年订单超 3 亿元；推出 8 寸 LTOI、LNOI 与 6 寸 SiCOI 等复合衬底；6-8 寸 SiC 复合衬底成果在 IEDM 发布"}],"funding":[{"date":"2026-10","round":"C+ 轮（中微临港增资）","amount":"本轮合计 2.5 亿元（中微临港 ≤3500 万元）","inv":"中微临港 + 其他 17 方；投前估值 67.5 亿元"},{"date":"2026-03","round":"战略融资","amount":"约 5 亿元","inv":"中微公司 / 孚腾资本（联合领投）/ 北汽产投 / 英诺基金（追加）"},{"date":"2026","round":"C / C+ 轮","amount":"超 6 亿元","inv":"（C、C+ 两轮合计增资超 6 亿元）"},{"date":"2024","round":"B+ / B++ 轮","amount":"超 2 亿元","inv":"（持续引入产业资本，加速 SiC/LNOI 复合衬底与键合设备量产）"},{"date":"2023","round":"B 轮","amount":"超 2 亿元","inv":"英诺基金等"},{"date":"2022","round":"A+ / A++ 轮","amount":"超 3 亿元","inv":"（同步收购日本常温键合设备公司，布局海外业务）"},{"date":"2021","round":"Pre-A / Pre-A+ 轮","amount":"近 2 亿元","inv":"（国内首台常温键合设备完成交付，填补行业空白）"},{"date":"2020","round":"天使轮","inv":"（公司成立，异质集成设备事业部设立）"}],"note":"键合集成领域国产替代代表：高端键合装备（尤其混合键合、超高真空常温键合）与复合衬底长期由 EVG（奥地利）、SUSS MicroTec（德国）、Tokyo Ohka、Adeka 等海外厂商主导；青禾晶元以「装备 + 工艺 + 材料」三线并进切入，是国内少数同时掌握常温键合、混合键合、临时键合全品类装备并具备复合衬底量产能力的企业，卡位 Chiplet / 3D 堆叠 / 硅光异质集成 / Micro-LED 核心装备环节。2025 年营收 9373.32 万元、净利润 -1.82 亿元；2026 年 1-7 月营收 1.56 亿元、净利润 -1.13 亿元，仍处产能与市场投入期。"}'::jsonb)
ON CONFLICT (name) DO UPDATE SET
  code = EXCLUDED.code, industry = EXCLUDED.industry, seg = EXCLUDED.seg, listed = EXCLUDED.listed,
